  it('keeps the usage an earlier round reported when a later round reports none', async () => {
    const usage: UsageMetadata = {inputTokens: 11, outputTokens: 3, totalTokens: 14};
    let seen: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, reported) => {
        seen = reported;
      },
    };
    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage}],
        [{type: 'text', text: 'done'}, STOP_DONE],
      ]),
      promptBuilder,
      registryReturning({result: 'r'}),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(seen).toEqual(usage);
  });

  it('resolves through a schema-rejected call, handing the rejection text to the corrected retry', async () => {
    const registry = new ToolRegistry();
    const executorInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'lookup',
        description: 'looks things up',
        inputSchema: {type: 'object', properties: {q: {type: 'string'}}, required: ['q']},
      },
      async input => {
        executorInputs.push(input);
        return `found ${String(input.q)}`;
      }
    );
    let rejectionSeenByProvider = '';
    let round = 0;
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        round += 1;
        const [lastContent] = params.messages.at(-1)?.content ?? [];
        if (lastContent?.type === 'tool_result') rejectionSeenByProvider = lastContent.content;
        if (round === 1) {
          yield {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {}}};
          yield STOP_FOR_TOOL;
          return;
        }
        if (round !== 2) {
          yield {type: 'text', text: 'found x'};
          yield STOP_DONE;
          return;
        }
        yield {type: 'tool_use', toolCall: {id: 'call-2', name: 'lookup', input: {q: 'x'}}};
        yield STOP_FOR_TOOL;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);

    const reply = await orchestrator.processMessage(createSession('ask'));

    expect(reply).toBe('found x');
    expect(executorInputs).toEqual([{q: 'x'}]);
    expect(rejectionSeenByProvider).toMatch(/q/);
    expect(rejectionSeenByProvider).toMatch(/required/i);
  });
});

