import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';
import type {ToolDefinition} from '../../types/ai.js';

const locationOnly = (): ToolDefinition => ({
  name: 'fetch_weather',
  description: 'unit fixture for schema validation',
  inputSchema: {
    type: 'object',
    properties: {location: {type: 'string'}},
    required: ['location'],
  },
});

const countingExecutor = () => {
  let calls = 0;
  return {
    run: async (): Promise<string> => {
      calls += 1;
      return 'ok';
    },
    calls: () => calls,
  };
};

describe('ToolRegistry schema validation', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('rejects a call missing the required location and leaves the executor unused', async () => {
    const registry = new ToolRegistry();
    const executor = countingExecutor();
    registry.register(locationOnly(), executor.run);

    const rejection = await registry.execute('fetch_weather', {});

    expect(rejection.result).toMatch(/location/);
    expect(rejection.result).toMatch(/required/i);
    expect(executor.calls()).toBe(0);
  });

  it('rejects a wrong-typed value naming the field and expected type, never the value', async () => {
    const lines: string[] = [];
    const capture = (message: string, fields?: Record<string, unknown>): void => {
      lines.push(`${message} ${JSON.stringify(fields ?? null)}`);
    };
    setLogger({debug: capture, info: capture, warn: capture, error: capture});
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'find_person',
        description: 'unit fixture for value redaction',
        inputSchema: {type: 'object', properties: {ssn: {type: 'string'}}, required: ['ssn']},
      },
      async () => 'unused'
    );

    const rejection = await registry.execute('find_person', {ssn: 123456789});

    expect(rejection.result).toContain('ssn');
    expect(rejection.result).toContain('string');
    expect(rejection.result).not.toContain('123456789');
    expect(lines.join('\n')).not.toContain('123456789');
  });

  it('hands valid input with undeclared extra properties to the executor unchanged, exactly once', async () => {
    const registry = new ToolRegistry();
    const seen: Array<Record<string, unknown>> = [];
    registry.register(locationOnly(), async input => {
      seen.push(input);
      return 'ok';
    });

    const input = {location: 'Oslo', extra: 'not in the schema'};
    await registry.execute('fetch_weather', input);

    expect(seen).toEqual([input]);
  });

  it('refuses registration of a schema ajv cannot compile, naming the tool', () => {
    const registry = new ToolRegistry();
    const uncompilable: ToolDefinition = {
      name: 'broken_tool',
      description: 'unit fixture for register-time compilation',
      inputSchema: {type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}},
    };

    expect(() => registry.register(uncompilable, async () => 'unreachable')).toThrow(/broken_tool/);
  });

  it('validates each call against the schema the function source returns for that call', async () => {
    const registry = new ToolRegistry();
    const schemas = [
      {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      {type: 'object', properties: {city: {type: 'string'}}, required: ['city']},
    ];
    let call = 0;
    registry.register(
      () => ({
        name: 'fetch_weather',
        description: 'unit fixture for per-call resolution',
        inputSchema: schemas[call++ % schemas.length],
      }),
      async () => 'unused'
    );

    const first = await registry.execute('fetch_weather', {});
    const second = await registry.execute('fetch_weather', {});

    expect(first.result).toMatch(/location/);
    expect(second.result).toMatch(/city/);
  });

  it('compiles a static schema at register time only, across ten execute calls', async () => {
    const registry = new ToolRegistry();
    const executor = countingExecutor();
    const definition = locationOnly();
    registry.register(definition, executor.run);
    definition.inputSchema = {type: 'object', properties: {city: {type: 'string'}}, required: ['city']};

    for (let round = 0; round < 10; round += 1) {
      await registry.execute('fetch_weather', {location: 'Oslo'});
    }

    expect(executor.calls()).toBe(10);
  });

  it('still throws Unknown tool for a name that was never registered', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('never_registered', {})).rejects.toThrow('Unknown tool: never_registered');
  });
});

